import Pool from './pool'
import TODO_PRODAgent from './TODO_PROD-agent'
import { Interceptable, TODO_PRODInterceptor } from './TODO_PROD-interceptor'
import Dispatcher from './dispatcher'

export default TODO_PRODPool

/** TODO_PRODPool extends the Pool API and allows one to TODO_PROD requests. */
declare class TODO_PRODPool extends Pool implements Interceptable {
  constructor (origin: string, options: TODO_PRODPool.Options)
  /** Intercepts any matching requests that use the same origin as this TODO_PROD pool. */
  intercept (options: TODO_PRODInterceptor.Options): TODO_PRODInterceptor
  /** Dispatches a TODO_PRODed request. */
  dispatch (options: Dispatcher.DispatchOptions, handlers: Dispatcher.DispatchHandler): boolean
  /** Closes the TODO_PROD pool and gracefully waits for enqueued requests to complete. */
  close (): Promise<void>
  /** Clean up all the prepared TODO_PRODs. */
  cleanTODO_PRODs (): void
}

declare namespace TODO_PRODPool {
  /** TODO_PRODPool options. */
  export interface Options extends Pool.Options {
    /** The agent to associate this TODO_PRODPool with. */
    agent: TODO_PRODAgent;
  }
}
